function initials(name: string) {
  return name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join("").toUpperCase();
}

export function HubDashboard({ userName, userEmail }: { userName: string; userEmail: string | null }) {
  const [page, setPage] = useState<Page>("Overview");
  const [menuOpen, setMenuOpen] = useState(false);
  const [status, setStatus] = useState<IntegrationStatus | null>(null);

  useEffect(() => {
    fetch("/api/status").then((response) => response.ok ? response.json() : null).then(setStatus).catch(() => setStatus(null));
  }, []);

  function navigate(next: Page) {
    setPage(next);
    setMenuOpen(false);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  return (
    <div className="hub-shell">
      <button className={`sidebar-scrim ${menuOpen ? "open" : ""}`} aria-label="Close navigation" onClick={() => setMenuOpen(false)} />
      <aside className={`sidebar ${menuOpen ? "open" : ""}`}>
        <div className="brand"><span className="brand-mark">D</span><div><strong>DOVA HUB</strong><small>PRODUCT INTELLIGENCE</small></div></div>
        <div className="nav-label">WORKSPACE</div>
        {primaryNav.map((item) => <NavButton key={item} item={item} active={page === item} onClick={() => navigate(item)} />)}
        <div className="nav-label">OPERATIONS</div>
        {operationsNav.map((item) => <NavButton key={item} item={item} active={page === item} count={item === "Attention" ? attention.length : undefined} onClick={() => navigate(item)} />)}
        <div className="side-status">
          <strong>{status?.openai.configured ? "DOVA Intelligence ready" : "Checking integrations…"}</strong>
          <span>OneDrive {status?.oneDrive.configured ? "connected" : "not connected"} · private access boundary</span>
        </div>
      </aside>

      <div className="app-column">
        <header className="topbar">
          <button className="mobile-menu" aria-label="Open navigation" onClick={() => setMenuOpen(true)}>☰</button>
          <span className="top-title">{page}</span>
          <button className="search-button" onClick={() => navigate("DOVA Intelligence")}><span>⌕</span> Search the Hub or ask DOVA <kbd>AI</kbd></button>
          <button className="avatar" title={userEmail ?? userName} aria-label={`Account: ${userName}`}>{initials(userName)}</button>
        </header>
        <main className="content">
          <PageContent page={page} navigate={navigate} status={status} />
        </main>
      </div>

      <nav className="mobile-bottom" aria-label="Mobile navigation">
        {(["Overview", "DOVA Intelligence", "Projects", "Files", "Settings"] as Page[]).map((item) => (
          <button key={item} className={page === item ? "active" : ""} onClick={() => navigate(item)}><span>{icons[item]}</span>{item === "DOVA Intelligence" ? "Intel" : item}</button>
        ))}
      </nav>
    </div>
  );
}

function NavButton({ item, active, count, onClick }: { item: Page; active: boolean; count?: number; onClick: () => void }) {
  return <button className={`nav-button ${active ? "active" : ""}`} onClick={onClick}><span className="nav-icon">{icons[item]}</span>{item}{count ? <span className="count">{count}</span> : null}</button>;
}

function PageContent({ page, navigate, status }: { page: Page; navigate: (page: Page) => void; status: IntegrationStatus | null }) {
  if (page === "Overview") return <Overview navigate={navigate} status={status} />;
  if (page === "DOVA Intelligence") return <Intelligence status={status} />;
  if (page === "Projects") return <CloudLibrary kind="projects" />;
  if (page === "Files") return <CloudLibrary kind="files" />;
  if (page === "Workspaces") return <Workspaces />;
  if (page === "Products") return <Products />;
  if (page === "Attention") return <Attention />;
  if (page === "Activity") return <Activity />;
  if (page === "Repository Guide") return <Guide />;
  return <Settings status={status} />;
}

