function Intelligence({ status }: { status: IntegrationStatus | null }) {
  const [messages, setMessages] = useState<Message[]>([{ role: "assistant", text: "I’m DOVA Intelligence. I can help interpret the Hub’s current product and workspace context. OneDrive content is not available until that integration is connected." }]);
  const [prompt, setPrompt] = useState("");
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const suggested = useMemo(() => ["Summarise the current Hub setup.", "What configuration work remains?", "Explain the storage boundary in plain language."], []);

  async function send(event: FormEvent) {
    event.preventDefault();
    const text = prompt.trim();
    if (!text || sending) return;
    setPrompt(""); setError(null); setMessages((current) => [...current, { role: "user", text }]); setSending(true);
    try {
      const response = await fetch("/api/intelligence", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ prompt: text }) });
      const data = await response.json() as { answer?: string; error?: string };
      if (!response.ok || !data.answer) throw new Error(data.error || "DOVA Intelligence could not respond.");
      setMessages((current) => [...current, { role: "assistant", text: data.answer! }]);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "DOVA Intelligence could not respond."); }
    finally { setSending(false); }
  }

  return <><Heading title="DOVA Intelligence" description="A secure cloud reasoning layer for Hub context now, with OneDrive and workstation context added only after approval." />
    <div className="intel-layout"><section className="panel chat-panel"><div className="panel-head"><strong>Conversation</strong><span className={`badge ${status?.openai.configured ? "healthy" : "attention"}`}>{status?.openai.configured ? "Cloud ready" : "Checking"}</span></div><div className="chat-log" aria-live="polite">{messages.map((message, index) => <div key={`${message.role}-${index}`} className={`message ${message.role}`}>{message.text}</div>)}{sending ? <div className="message">Thinking…</div> : null}{error ? <p className="card-note error-note">{error}</p> : null}</div><form className="composer" onSubmit={send}><textarea value={prompt} maxLength={6000} onChange={(event) => setPrompt(event.target.value)} placeholder="Ask about products, workspaces, repository structure or next actions…" aria-label="Message DOVA Intelligence" /><div className="composer-row"><span>Hub context only · no OneDrive files connected</span><button className="button primary" disabled={sending || !prompt.trim()}>{sending ? "Working…" : "Send ↑"}</button></div></form></section>
      <aside className="context-stack"><article className="card context-card"><span className="card-label">CURRENT CONTEXT</span><h3>Repository Hub</h3><p>Products, workspaces, integration status and the approved storage policy.</p></article><article className="card context-card"><span className="card-label">SUGGESTED</span>{suggested.map((item) => <button key={item} className="prompt-chip" onClick={() => setPrompt(item)}>{item}</button>)}</article><article className="card context-card"><span className="card-label">BOUNDARY</span><h3>OneDrive disconnected</h3><p>DOVA Intelligence cannot see project files or client records at this stage.</p></article></aside>
    </div></>;
}
